// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { getLinksSearch, postLinksSearch, putLinksSearch } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // An accepted request: one ?q value, answered with the 200 envelope.
    const searchGetResponse = await getLinksSearch(client, headers, {"q": ["skyramp-guard-probe"]});
    expect(searchGetResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(searchGetResponse, "response").length, 'no record carries this token').toBe(0);
    expect(getResponseValue(searchGetResponse, "response.0"), 'response.0').toBeNull();
    expect(getResponseValue(searchGetResponse, "error"), 'error carries no value').toBeNull();

    // A method the endpoint does not serve must be refused with 405.
    const searchPostResponse = await postLinksSearch(client, headers);
    expect(searchPostResponse.statusCode, 'status code').toBe(405);
    expect(getResponseValue(searchPostResponse, "response"), 'response').toBe("Method not allowed.");

    // PUT is refused with 405 as well.
    const searchPutResponse = await putLinksSearch(client, headers);
    expect(searchPutResponse.statusCode, 'status code').toBe(405);
    expect(getResponseValue(searchPutResponse, "response"), 'response').toBe("Method not allowed.");

    // Repeating ?q makes Next.js hand the handler a string[]. The endpoint must reject the
    // malformed query with a 400 and its normal JSON envelope, not crash with an unhandled 5xx.
    const searchGet1Response = await getLinksSearch(client, headers, {"q": ["alpha", "beta"]}, 400);
    expect(searchGet1Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(searchGet1Response, "response"), 'response envelope is present').not.toBeNull();
});
